from pathlib import Path

path = Path("SignalSelectionWizardWindow.xaml")
text = path.read_text(encoding="utf-8")

resources_anchor = '''        </Style>\n    </Window.Resources>'''
style = '''        </Style>\n\n        <!-- Modern search-field clear affordance: quiet at rest, obvious on hover/focus,\n             and large enough to hit without looking like a separate toolbar button. -->\n        <Style x:Key="GlobalSearchClearButton" TargetType="Button">\n            <Setter Property="Width" Value="28"/>\n            <Setter Property="Height" Value="28"/>\n            <Setter Property="Padding" Value="0"/>\n            <Setter Property="Margin" Value="2,0,3,0"/>\n            <Setter Property="Background" Value="Transparent"/>\n            <Setter Property="BorderBrush" Value="Transparent"/>\n            <Setter Property="BorderThickness" Value="1"/>\n            <Setter Property="Foreground" Value="#667085"/>\n            <Setter Property="Cursor" Value="Hand"/>\n            <Setter Property="HorizontalContentAlignment" Value="Center"/>\n            <Setter Property="VerticalContentAlignment" Value="Center"/>\n            <Setter Property="FocusVisualStyle" Value="{x:Null}"/>\n            <Setter Property="ClipToBounds" Value="False"/>\n            <Setter Property="Template">\n                <Setter.Value>\n                    <ControlTemplate TargetType="Button">\n                        <Border x:Name="Chrome"\n                                Width="28" Height="28"\n                                CornerRadius="8"\n                                Background="{TemplateBinding Background}"\n                                BorderBrush="{TemplateBinding BorderBrush}"\n                                BorderThickness="{TemplateBinding BorderThickness}"\n                                SnapsToDevicePixels="True">\n                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>\n                        </Border>\n                        <ControlTemplate.Triggers>\n                            <Trigger Property="IsMouseOver" Value="True">\n                                <Setter TargetName="Chrome" Property="Background" Value="#EEF3F8"/>\n                                <Setter TargetName="Chrome" Property="BorderBrush" Value="#D8E2EC"/>\n                                <Setter Property="Foreground" Value="#475467"/>\n                            </Trigger>\n                            <Trigger Property="IsPressed" Value="True">\n                                <Setter TargetName="Chrome" Property="Background" Value="#E3EBF4"/>\n                                <Setter TargetName="Chrome" Property="BorderBrush" Value="#C9D7E5"/>\n                            </Trigger>\n                            <Trigger Property="IsKeyboardFocused" Value="True">\n                                <Setter TargetName="Chrome" Property="Background" Value="#EEF4FF"/>\n                                <Setter TargetName="Chrome" Property="BorderBrush" Value="#7AA7F7"/>\n                                <Setter Property="Foreground" Value="#2563EB"/>\n                            </Trigger>\n                            <Trigger Property="IsEnabled" Value="False">\n                                <Setter TargetName="Chrome" Property="Opacity" Value="0.45"/>\n                            </Trigger>\n                        </ControlTemplate.Triggers>\n                    </ControlTemplate>\n                </Setter.Value>\n            </Setter>\n        </Style>\n    </Window.Resources>'''
if text.count(resources_anchor) != 1:
    raise SystemExit(f"Window.Resources anchor count={text.count(resources_anchor)}")
text = text.replace(resources_anchor, style, 1)

old_button = '''                        <Button Grid.Column="2"\n                                Content="×"\n                                Style="{StaticResource MiniChipButton}"\n                                Padding="8,2"\n                                Margin="3"\n                                Click="ClearGlobalFilter_Click"\n                                ToolTip="Clear global search"/>'''
new_button = '''                        <Button x:Name="GlobalSearchClearButton"\n                                Grid.Column="2"\n                                Style="{StaticResource GlobalSearchClearButton}"\n                                Click="ClearGlobalFilter_Click"\n                                ToolTip="Clear search"\n                                AutomationProperties.Name="Clear global search">\n                            <Button.Style>\n                                <Style TargetType="Button" BasedOn="{StaticResource GlobalSearchClearButton}">\n                                    <Style.Triggers>\n                                        <DataTrigger Binding="{Binding Text, ElementName=GlobalSearchTextBox}" Value="">\n                                            <Setter Property="Visibility" Value="Collapsed"/>\n                                        </DataTrigger>\n                                    </Style.Triggers>\n                                </Style>\n                            </Button.Style>\n                            <Viewbox Width="14" Height="14"\n                                     HorizontalAlignment="Center" VerticalAlignment="Center"\n                                     Stretch="Uniform" SnapsToDevicePixels="True">\n                                <Path Data="{StaticResource LucideX}"\n                                      Fill="Transparent"\n                                      Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType={x:Type Button}}}"\n                                      StrokeThickness="1.9"\n                                      StrokeStartLineCap="Round" StrokeEndLineCap="Round"\n                                      StrokeLineJoin="Round"/>\n                            </Viewbox>\n                        </Button>'''
if text.count(old_button) != 1:
    raise SystemExit(f"Legacy clear button anchor count={text.count(old_button)}")
text = text.replace(old_button, new_button, 1)

path.write_text(text, encoding="utf-8", newline="\n")
print("Applied modern Lucide global-search clear control.")
